long get_decompression_value() {
    inflate_state* state = NULL;

    if (strm == NULL || strm->state == NULL) {
        return -1; // Error value for invalid stream or state
    }

    state = (inflate_state*)strm->state;

    long result = (long)(state->back << 16);

    switch (state->mode) {
        case COPY:
            result += state->length;
            break;
        case MATCH:
            result += (state->was - state->length);
            break;
        default:
            // Default case for unknown mode
            return -1;
    }

    return result;
}
